def is_safe(board, row, col, n):
    for i in range(row):
        if board[i] == col or board[i] - i == col - row or board[i] + i == col + row:
            return False
    return True

def solve_n_queens(n):
    board = [-1] * n
    def backtrack(row):
        if row == n:
            return True
        for col in range(n):
            if is_safe(board, row, col, n):
                board[row] = col
                if backtrack(row + 1):
                    return True
                board[row] = -1
        return False
    if backtrack(0):
        return board
    return None

solution = solve_n_queens(7)
print(solution)
